import AppKit
import Foundation
import KernovaFileTree
import KernovaWire
import UniformTypeIdentifiers

extension ClipboardPasteboardReader {
    /// What a pasteboard offers.
    public enum OfferOutcome {
        /// The pasteboard holds no item at all.
        case empty

        /// An `org.nspasteboard.TransientType` or `AutoGeneratedType` marker
        /// dropped the whole pasteboard: no deliberate copy put it there, so
        /// nothing is offered.
        case suppressed(ClipboardSnapshotPolicy.SkipReason)

        /// The offer, with `lost` counting the pasteboard's items it leaves
        /// out: files gone or unreadable since the copy.
        case offer(ClipboardOfferSource, lost: Int)

        /// The pasteboard held items and none of them is offerable; `lost`
        /// counts those whose file is gone or unreadable.
        case nothingOfferable(lost: Int)
    }

    /// One pasteboard item, classified on the main actor.
    private enum PendingItem: Sendable {
        /// Inline types of pasteboard item `item`, none of them read.
        case inline(item: Int, types: [String])
        /// A file or folder on disk, not yet looked at; an image file also offers its bytes INLINE when
        /// `inliningImage`. `promise` is the item's file promise, offered in its place when the file cannot be
        /// opened.
        case file(URL, inliningImage: Bool, promise: (index: Int, representation: Representation)?)
        /// A file promise: the index of its receiver, and its representation.
        case promise(Int, Representation)
        /// A file a called-in promise lands, and its representation.
        case landing(Task<URL, any Error>, Representation)
    }

    /// Reads what `pasteboard` offers, one offered item per pasteboard item,
    /// reading no content.
    ///
    /// - An item naming a file on disk offers it as FILE or FOLDER under the
    ///   name it was copied by, an image file also offering its bytes INLINE.
    ///   The URL is the one thing read from the pasteboard: an item's name and
    ///   storage are in the offer.
    /// - `promises` are the receivers `readObjects(forClasses:
    ///   [NSFilePromiseReceiver.self])` yields: one per item that carries one
    ///   (``carriesPromiseReceiver(_:)``), in order. Every such item takes the
    ///   next, whether or not it offers it. An item naming no file on disk
    ///   offers its receiver `promised`: it is called in only when pulled, into
    ///   a directory `promiseDestination` makes, and offered under the name the
    ///   promise gives so far.
    /// - Any other item offers each of its types INLINE, its bytes read from
    ///   the pasteboard when pulled, and only while the pasteboard is
    ///   unchanged. Marker and file-reference types are never offered, nor the
    ///   path text of a file copy.
    ///
    /// `org.nspasteboard.ConcealedType` on any item marks the offer concealed;
    /// `TransientType` or `AutoGeneratedType` suppresses it. Stat-ing the
    /// files, and `sizeOf`'s folder estimate, run off the main actor and
    /// download no dataless file (``readableSource(for:opening:)``).
    public static func readOffer(
        from pasteboard: any ClipboardReadPasteboard,
        promises: [any FilePromiseReceiving] = [],
        promiseDestination: @escaping @MainActor () throws -> URL = { throw ClipboardServeError.unavailable },
        sizeOf: (@Sendable (URL) -> Int)? = { ClipboardArchive.estimatedByteCount(at: $0) }
    ) async -> OfferOutcome {
        await read(pasteboard, promises: promises, calledIn: [], rule: .clipboard, sizeOf: sizeOf) {
            try promiseDestination()
        }
    }

    /// What a pasteboard holds as a snapshot.
    public enum SnapshotOutcome {
        /// The pasteboard holds no item, or a marker suppressed it, or none of its items is offerable: nothing
        /// to copy.
        case nothing
        /// The snapshot (``ClipboardOfferSource/snapshot()``), with `lost` counting the items it leaves out.
        case snapshot(ClipboardOfferSource, lost: Int)
        /// The pasteboard held items naming files, and none of them could be read: nothing to copy.
        case unreadable
        /// The pasteboard changed while it was read, twice.
        case changed
        /// What is not a file or folder came to more than the ceiling: nothing is copied.
        case tooLarge(limitBytes: Int)
    }

    /// A snapshot of `pasteboard` now: every representation that is not a file or folder read whole, so nothing
    /// the pasteboard holds later reaches it, and each file kept as the reference it is. A pasteboard that
    /// changed while it was read is read once more.
    ///
    /// A pasteboard holding a write of this process (`ledger`) is never read: it is snapshotted from what the
    /// write was made from (``ClipboardWriteSource``). What it holds only as the far side's promise is named by
    /// reference when the write serves an offer that arrived on `destination`, the connection the snapshot's copy
    /// goes over; otherwise it is the write's own source's, what is not a file pulled through it now and each file
    /// pulled through it when pulled, while that offer lasts. Any other pasteboard is read as
    /// ``readOffer(from:promises:promiseDestination:sizeOf:)`` reads it, its file promises called in now into a
    /// ``ClipboardFileStaging/lease()`` of `staging` the snapshot holds, so they live as long as it does; with no
    /// `staging`, a promise lands nothing. No more than `ceiling` bytes of what is not a file are read.
    public static func readSnapshot(
        from pasteboard: any ClipboardReadPasteboard,
        ceiling: Int = ClipboardPasteLimit.defaultBytes,
        ledger: ClipboardWriteLedger = .shared,
        staging: ClipboardFileStaging? = nil,
        copyingTo destination: ClipboardConnectionID?,
        sizeOf: (@Sendable (URL) -> Int)? = { ClipboardArchive.estimatedByteCount(at: $0) }
    ) async -> SnapshotOutcome {
        do throws(ClipboardSnapshotTooLarge) {
            for _ in 0..<2 {
                if let written = ledger.standingWrite(on: pasteboard) {
                    guard
                        let (snapshot, lost) = try await ClipboardOfferSource.snapshot(
                            of: written, on: pasteboard, copyingTo: destination, inlineCeiling: ceiling)
                    else { return .nothing }
                    return .snapshot(snapshot, lost: lost)
                }
                let lease = staging?.lease()
                let read = await readOffer(
                    from: pasteboard, promises: pasteboard.filePromiseReceivers,
                    promiseDestination: {
                        guard let lease else { throw ClipboardServeError.unavailable }
                        return try lease.reserveScratchDirectory()
                    }, sizeOf: sizeOf)
                if case .nothingOfferable(let lost) = read, lost > 0 { return .unreadable }
                guard case .offer(let source, let lost) = read else { return .nothing }
                if let snapshot = try await source.snapshot(inlineCeiling: ceiling, holding: lease) {
                    return .snapshot(snapshot, lost: lost)
                }
                guard pasteboard.changeCount != source.changeCount else { return .nothing }
            }
            return .changed
        } catch {
            return .tooLarge(limitBytes: error.limitBytes)
        }
    }

    /// Reads what a drop of `pasteboard` offers: one item per file or folder a pasteboard item names on disk,
    /// and one per file a pasteboard item's file promise names, each a single FILE or FOLDER representation,
    /// reading no content.
    ///
    /// `promises` are the drop's promises, called in already (``CalledInFilePromise/callIn(_:into:)``), so
    /// each file is offered under the name its source gave once called in. An item carrying a promise offers
    /// it even beside a file URL: the promise is what the source means to hand over, where a Photos asset's
    /// URL names the library's smaller derivative of it. An item that is neither is not offered.
    public static func readDropOffer(
        from pasteboard: any ClipboardReadPasteboard, promises: [CalledInFilePromise],
        sizeOf: (@Sendable (URL) -> Int)? = { ClipboardArchive.estimatedByteCount(at: $0) }
    ) async -> OfferOutcome {
        await read(
            pasteboard, promises: promises.map(\.receiver), calledIn: promises, rule: .drop, sizeOf: sizeOf
        ) { throw ClipboardServeError.unavailable }
    }

    /// Which pasteboard items an offer carries, and how.
    private enum Rule {
        /// Every item: a file on disk as FILE or FOLDER, an image file's bytes INLINE beside it; a promise
        /// when no file on disk is named; any other item's types INLINE.
        case clipboard
        /// Files, folders and promises only, a promise before a file on disk, one representation each.
        case drop
    }

    private static func read(
        _ pasteboard: any ClipboardReadPasteboard, promises: [any FilePromiseReceiving],
        calledIn: [CalledInFilePromise], rule: Rule, sizeOf: (@Sendable (URL) -> Int)?,
        promiseDestination: @escaping @MainActor () throws -> URL
    ) async -> OfferOutcome {
        let pasteboardItems = pasteboard.items
        guard !pasteboardItems.isEmpty else { return .empty }
        let changeCount = pasteboard.changeCount
        let markers = ClipboardSnapshotPolicy.Markers(
            types: pasteboardItems.lazy.flatMap { $0.types.lazy.map(\.rawValue) })
        if markers.transient { return .suppressed(.transientSnapshot) }
        if markers.autoGenerated { return .suppressed(.autoGeneratedSnapshot) }

        var pending: [PendingItem] = []
        var lost = 0
        var nextPromise = promises.startIndex
        for (index, item) in pasteboardItems.enumerated() {
            var receiver: Int?
            if carriesPromiseReceiver(item), nextPromise < promises.endIndex {
                receiver = nextPromise
                nextPromise += 1
            }
            if rule == .drop, let receiver {
                let promise = calledIn[receiver]
                for (index, file) in promise.files.enumerated() {
                    let representation = promisedRepresentation(promise.receiver, file: index, named: file.name)
                    pending.append(.landing(file.landed, representation))
                }
                continue
            }
            let resolution = fileURLResolution(in: item)
            if case .resolved(let url) = resolution {
                let promise = receiver.map { ($0, promisedRepresentation(promises[$0])) }
                pending.append(.file(url, inliningImage: rule == .clipboard, promise: promise))
                continue
            }
            if case .notAFile = resolution, let receiver {
                pending.append(.promise(receiver, promisedRepresentation(promises[receiver])))
                continue
            }
            if case .vanished = resolution, rule == .drop {
                lost += 1
                continue
            }
            guard rule == .clipboard else { continue }
            let types = item.types.map(\.rawValue)
            let isFileItem = types.contains(where: ClipboardSnapshotPolicy.isFileReference(uti:))
            let offerable = types.filter {
                !ClipboardSnapshotPolicy.shouldSkipBeforeReading(uti: $0) && !(isFileItem && isPathFallbackType($0))
            }
            if !offerable.isEmpty {
                pending.append(.inline(item: index, types: offerable))
            } else if case .vanished = resolution {
                lost += 1
            }
        }

        let resolved = await Task.detached {
            DatalessMaterialization.off.during { pending.map { resolve($0, sizeOf: sizeOf) } }
        }.value
        var items: [OfferedItem] = []
        var origins: [[ClipboardOfferSource.Origin]] = []
        for entry in resolved {
            guard let entry else {
                lost += 1
                continue
            }
            items.append(entry.item)
            origins.append(entry.origins)
        }
        guard !items.isEmpty else { return .nothingOfferable(lost: lost) }
        let source = ClipboardOfferSource(
            items: items, origins: origins, concealed: markers.concealed,
            pasteboard: pasteboard, changeCount: changeCount, promises: promises,
            promiseDestination: promiseDestination)
        return .offer(source, lost: lost)
    }

    /// The offered item for `pending`, or nil when its file is gone or
    /// unreadable.
    nonisolated private static func resolve(
        _ pending: PendingItem, sizeOf: (@Sendable (URL) -> Int)?
    ) -> (item: OfferedItem, origins: [ClipboardOfferSource.Origin])? {
        switch pending {
        case .inline(let index, let types):
            var item = OfferedItem()
            item.representations = types.map { .make(TypeDescriptor(appleUTI: $0), .inline, size: 0) }
            return (item, types.map { .pasteboard(item: index, type: $0) })
        case .promise(let index, let representation):
            return (.with(representation), [.promise(index)])
        case .landing(let file, let representation):
            return (.with(representation), [.landing(file)])
        case .file(let url, let inliningImage, let promise):
            // Named as the user copied it, its bytes read from what it resolves to.
            guard let source = readableSource(for: url),
                let values = try? source.resourceValues(forKeys: [.contentTypeKey, .isDirectoryKey, .fileSizeKey])
            else {
                // A file this process cannot open is never offered; the item's promise, called in, writes one it can.
                return promise.map { (.with($0.representation), [.promise($0.index)]) }
            }
            let name = url.lastPathComponent
            if values.isDirectory == true {
                let type = TypeDescriptor(appleUTI: values.contentType?.identifier ?? UTType.folder.identifier)
                return (.with(.make(type, .folder, size: sizeOf?(source) ?? 0, name: name)), [.folder(source)])
            }
            guard let contentType = values.contentType, let size = values.fileSize else { return nil }
            let type = TypeDescriptor(appleUTI: contentType.identifier)
            var item = OfferedItem.with(.make(type, .file, size: size, name: name))
            var origins: [ClipboardOfferSource.Origin] = [.file(source)]
            if inliningImage, contentType.conforms(to: .image) {
                item.representations.append(.make(type, .inline, size: size))
                origins.append(.fileContents(source))
            }
            return (item, origins)
        }
    }

    /// A promise's representation of its first file, named by the first name
    /// it gives so far.
    private static func promisedRepresentation(_ receiver: any FilePromiseReceiving) -> Representation {
        promisedRepresentation(receiver, file: 0, named: receiver.fileNames.first(where: { !$0.isEmpty }) ?? "")
    }

    /// A promise's representation of its file `index`: FOLDER when the file
    /// type the promise declares for it — its first when it declares fewer —
    /// is a directory, FILE otherwise, named `name` as `Representation.make`
    /// names one.
    private static func promisedRepresentation(
        _ receiver: any FilePromiseReceiving, file index: Int, named name: String
    ) -> Representation {
        let types = receiver.fileTypes
        let contentType = (types.indices.contains(index) ? types[index] : types.first).flatMap { UTType($0) }
        let isFolder = contentType?.conforms(to: .directory) == true
        let fallbackType: UTType = isFolder ? .folder : .data
        return .make(
            TypeDescriptor(appleUTI: (contentType ?? fallbackType).identifier), isFolder ? .folder : .file,
            size: 0, name: name, promised: true)
    }
}
